#!/usr/bin/env python3
"""attest_v1_oracle.py — writes attest_v1.txt, the message-byte fixtures of the
ML-DSA-87 companion library (design docs/plans/2026-10-22-mldsa87-companion-
library-design.md rev 2 §1.3, §1.7; local).

What it does: encodes, BY HAND (no ABI library, no keccak), the signed message
    abi.encode(bytes32 TAG_ATTEST_V1, uint256 chainid, address contract,
               bytes32 actionType, uint256 nonce, uint64 expiry, address signer,
               p1, ..., pn)
for two cases, one with static parameters only and one with a dynamic `bytes`
parameter (so the offset word and the tail are exercised), and prints the
fixture to stdout.

What it pins and what it does NOT: the ABI LAYOUT (word order, static words,
the dynamic offset relative to the start of the whole tuple, the length word,
the right zero padding). The two hash words are INPUTS copied in, not derived
here — Python on this machine has no keccak:
  - TAG_ATTEST_V1 = keccak256("nodus.evm.attest.message.v1"), the bytes of the
    operator's decision (decisions/2026-10-21-mldsa87-evm-precompile.md);
  - actionType = keccak256(action text), computed with the tree's
    shared/crypto/hash/keccak256.c (2026-10-22; the same program gave the
    empty-string vector c5d24601...a470 and the decision's TAG bytes).
The independent hash check is the engine test, which compares these words with
the Solidity compiler's own compile-time keccak256 (a separate implementation).

Requires: python3 only. Run with -I. Leaves nothing behind.
    python3 -I attest_v1_oracle.py > attest_v1.txt
"""

TAG_ATTEST_V1 = bytes.fromhex(
    "99e805e35026bce860f6bbcda7466a18fd6a7bfe81d1524494fe541c9488a43d")

ACTION_TYPE = {
    "Approve(uint256,address)": bytes.fromhex(
        "47ad3e4b0f4bdbe3ac08708bbc45053d2ff616911b39e65563fd9bd781909645"),
    "Submit(address,uint256,bytes)": bytes.fromhex(
        "73bd4d814668bb6b74075c6bf5748d7b0a436654ff93fb427293f570d560818a"),
}

CHAIN_ID = bytes(0xc0 + i for i in range(32))   # test_contract_lib.c chain_id_word
CONTRACT = bytes(0xa0 + i for i in range(32))   # high bytes non-zero on purpose
SIGNER = bytes(0x50 + i for i in range(32))

U256_MAX = (1 << 256) - 1
U64_MAX = (1 << 64) - 1


def word_uint(v, bits=256):
    assert 0 <= v < (1 << bits)
    return v.to_bytes(32, "big")


def word_b32(b):
    assert len(b) == 32
    return bytes(b)


def tail_bytes(b):
    padded = bytes(b) + bytes((32 - len(b) % 32) % 32)
    return word_uint(len(b)) + padded


def encode(params):
    """params: list of (kind, value), kind in uint256/uint64/address/bytes32/bytes."""
    head, tail = [], []
    head_len = 32 * len(params)
    for kind, v in params:
        if kind == "uint256":
            head.append(word_uint(v))
        elif kind == "uint64":
            head.append(word_uint(v, 64))
        elif kind in ("address", "bytes32"):
            head.append(word_b32(v))
        elif kind == "bytes":
            head.append(word_uint(head_len + sum(len(t) for t in tail)))
            tail.append(tail_bytes(v))
        else:
            raise ValueError(kind)
    return b"".join(head) + b"".join(tail)


def header(action, nonce, expiry):
    return [("bytes32", TAG_ATTEST_V1), ("uint256", int.from_bytes(CHAIN_ID, "big")),
            ("address", CONTRACT), ("bytes32", ACTION_TYPE[action]),
            ("uint256", nonce), ("uint64", expiry), ("address", SIGNER)]


CASES = [
    {
        "name": "static",
        "action": "Approve(uint256,address)",
        "nonce": 7,
        "expiry": 1800000000,
        "params": [("uint256", 1000), ("address", bytes([0x77] * 31 + [0x01]))],
        "args": ["1000", "77" * 31 + "01"],
    },
    {
        "name": "dynamic",
        "action": "Submit(address,uint256,bytes)",
        "nonce": U256_MAX,
        "expiry": U64_MAX,
        "params": [("address", bytes([0x88] * 32)), ("uint256", 10 ** 18),
                   ("bytes", bytes.fromhex("deadbeef01"))],
        "args": ["88" * 32, str(10 ** 18), "deadbeef01"],
    },
]


def main():
    print("# attest_v1.txt — GENERATED by attest_v1_oracle.py (python3 -I attest_v1_oracle.py > attest_v1.txt).")
    print("# Message-byte fixtures of the ML-DSA-87 companion library: the ABI LAYOUT is encoded by hand;")
    print("# TAG_ATTEST_V1 and actionType are copied inputs (see the oracle's docstring), not derived.")
    print("# One case per block; blank line between cases. Hex without 0x. Integers in decimal.")
    print("# Fields: case, action, actiontype, chain, contract, nonce, expiry, signer, args (the CLI's")
    print("# positional parameter values, space separated), message.")
    for c in CASES:
        msg = encode(header(c["action"], c["nonce"], c["expiry"]) + c["params"])
        assert len(msg) % 32 == 0 and len(msg) <= 65536
        assert msg[:224] == encode(header(c["action"], c["nonce"], c["expiry"]))
        print()
        print("case " + c["name"])
        print("action " + c["action"])
        print("actiontype " + ACTION_TYPE[c["action"]].hex())
        print("chain " + CHAIN_ID.hex())
        print("contract " + CONTRACT.hex())
        print("nonce " + str(c["nonce"]))
        print("expiry " + str(c["expiry"]))
        print("signer " + SIGNER.hex())
        print("args " + " ".join(c["args"]))
        print("message " + msg.hex())


if __name__ == "__main__":
    main()
